/** Record the actual CLI producer for this consumer, not just the surveyed prototypes. */
export function buildGpuiNativeStyleFiles(requested: Iterable<string>): {
  files: NonNullable<GeneratedModule['supportingFiles']>;
  unknown: string[];
} {
  const path = '.proto-ui/fixtures/style-tokens.json';
  const baseline = JSON.parse(
    gpuiNativeStyleFiles.find((file) => file.path === path)!.contents
  ) as {
    tokens: Record<string, Record<string, string>>;
    order: string[];
    noDeclarations: string[];
  };
  const tokens = [
    ...new Set([...Object.keys(baseline.tokens), ...baseline.noDeclarations, ...requested]),
  ].sort();
  const wanted = new Set(tokens),
    markers = new Set(baseline.noDeclarations);
  const declarations = new Map<string, Record<string, string>>(),
    order: string[] = [];
  // Same producer/selector extraction as scripts/gpui/generate-style-fixture.mts.
  const css = renderProtoStyleTokenCss(tokens);
  const pattern = /:where\(\[data-pui-style~="((?:[^"\\]|\\.)*)"\]\)\s*\{([^}]*)\}/g;
  for (const match of css.matchAll(pattern)) {
    const token = match[1]!.replace(/\\(.)/g, '$1');
    if (!wanted.has(token)) continue;
    if (!declarations.has(token)) {
      declarations.set(token, {});
      order.push(token);
    }
    const values = declarations.get(token)!;
    for (const entry of match[2]!.split(';')) {
      const colon = entry.indexOf(':');
      if (colon < 0) continue;
      const property = entry.slice(0, colon).trim(),
        value = entry.slice(colon + 1).trim();
      if (property && value) values[property] = value;
    }
  }
  const unknown = tokens.filter((token) => !declarations.has(token) && !markers.has(token));
  const fixture = JSON.stringify({
    source: 'packages/cli/src/services/proto-style-css.ts',
    note: 'Consumer-specific output of renderProtoStyleTokenCss; no Rust utility grammar.',
    tokens: Object.fromEntries(declarations),
    order,
    noDeclarations: [...markers],
  });
  return {
    files: gpuiNativeStyleFiles.map((file) =>
      file.path === path ? { ...file, contents: fixture } : file
    ),
    unknown,
  };
}
